// Real-gameplay compute shader metadata for Zelda: Ocarina of Time (Switch 2, 0400486024DEC000).
// Contains ONLY numeric shader hashes, workgroup sizes, shared memory sizes, and descriptor/cbuf
// hints (zero Nintendo shader bytecode).
struct OotComputeTexType {
    u32 key;
    u32 value;
};

struct OotComputeTexFmt {
    u32 key;
    u32 value;
};

struct OotComputeCbuf {
    u64 key;
    u32 value;
};

struct OotComputeSpt {
    u64 key;
    u8 value;
};

struct OotComputeMeta {
    u64 hash;
    u32 shared_memory_size;
    std::array<u32, 3> workgroup_size;
    u32 tt_off, tt_cnt;
    u32 tpf_off, tpf_cnt;
    u32 cb_off, cb_cnt;
    u32 spt_off, spt_cnt;
};

