[[nodiscard]] inline const OotComputeMeta* FindOotComputeMeta(u64 hash) noexcept {
    const auto it = std::lower_bound(
        OOT_COMPUTE_META.begin(), OOT_COMPUTE_META.end(), hash,
        [](const OotComputeMeta& entry, u64 target) { return entry.hash < target; });
    return (it != OOT_COMPUTE_META.end() && it->hash == hash) ? &(*it) : nullptr;
}

